python3 - <<'PY'
import json, uuid

FLOW_PATH = '/work/output/artifacts/skill-flow-eval-inline-agent/TriageEval/TriageEval/TriageEval.flow'
AGENT_SOURCE = '6d7bd065-2db5-4540-895c-dc92ce2c7248'

# Load registry definitions
end_def   = json.load(open('/tmp/end_def.json'))['Data']['Node']
agent_def = json.load(open('/tmp/agent_def.json'))['Data']['Node']

# Load current flow for existing trigger node + definition + layout
cur = json.load(open(FLOW_PATH))
trigger_node = cur['nodes'][0]
trigger_def  = cur['definitions'][0]
start_layout = cur['layout']['nodes']['start']

flow = {
  "id": cur['id'],
  "version": cur['version'],
  "name": cur['name'],
  "nodes": [
    trigger_node,
    {
      "id": "autonomousAgent1",
      "type": "uipath.agent.autonomous",
      "typeVersion": "1.2",
      "display": {"label": "Classify Email"},
      "inputs": {
        "systemPrompt": "Classify the email into category and priority.",
        "userPrompt": "Email:\n{{input.start__output__email}}",
        "source": AGENT_SOURCE,
        "agentInputVariables": [
          {
            "id": "start__output__email",
            "type": "string",
            "binding": "=$vars.start.output.email",
            "description": "Bound from $vars.start.output.email"
          }
        ],
        "agentOutputVariables": [
          {"id": "category", "type": "string"},
          {"id": "priority", "type": "string"}
        ]
      },
      "outputs": {
        "output": {
          "type": "object",
          "description": "Agent response",
          "source": "=result.response",
          "var": "output"
        },
        "error": {
          "type": "object",
          "description": "Error information if the node fails",
          "source": "=Error",
          "var": "error"
        }
      }
    },
    {
      "id": "end1",
      "type": "core.control.end",
      "typeVersion": "1.0",
      "display": {"label": "End"},
      "inputs": {},
      "outputs": {
        "category": {"source": "=js:$vars.autonomousAgent1.output.category"},
        "priority":  {"source": "=js:$vars.autonomousAgent1.output.priority"}
      }
    }
  ],
  "edges": [
    {
      "id": "edge-start-to-agent",
      "sourceNodeId": "start",
      "sourcePort": "output",
      "targetNodeId": "autonomousAgent1",
      "targetPort": "input"
    },
    {
      "id": "edge-agent-to-end",
      "sourceNodeId": "autonomousAgent1",
      "sourcePort": "success",
      "targetNodeId": "end1",
      "targetPort": "input"
    }
  ],
  "definitions": [trigger_def, agent_def, end_def],
  "variables": {
    "globals": [
      {"id": "email",    "direction": "in",  "type": "string", "triggerNodeId": "start"},
      {"id": "category", "direction": "out", "type": "string"},
      {"id": "priority", "direction": "out", "type": "string"}
    ],
    "nodes": [
      {"id": str(uuid.uuid4()), "binding": {"nodeId": "autonomousAgent1", "outputId": "output"}},
      {"id": str(uuid.uuid4()), "binding": {"nodeId": "autonomousAgent1", "outputId": "error"}}
    ]
  },
  "layout": {
    "nodes": {
      "start": start_layout,
      "autonomousAgent1": {"position": {"x": 0, "y": 0}, "size": {"width": 288, "height": 96}, "collapsed": False},
      "end1":             {"position": {"x": 0, "y": 0}, "size": {"width": 96,  "height": 96}, "collapsed": False}
    }
  }
}

with open(FLOW_PATH, 'w') as f:
    json.dump(flow, f, indent=2)

print('Flow written OK')
PY

